// ============================================================
// THĂM DÒ 5 NGUỒN DỮ LIỆU KHỐI NGOẠI - mã thử: VNM
// Chạy xong gửi kết quả (tab JSON) để chọn nguồn sống.
// ============================================================
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';

const sources = [
  {
    name: 'A. VNDirect finfo (api-finfo)',
    url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:VNM&size=5&sort=tradingDate:desc',
    headers: { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' },
  },
  {
    name: 'B. VNDirect finfo (finfo-api)',
    url: 'https://finfo-api.vndirect.com.vn/v4/foreigns?q=code:VNM&size=5&sort=tradingDate:desc',
    headers: { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' },
  },
  {
    name: 'C. DNSE - thông tin mã',
    url: 'https://services.entrade.com.vn/dnse-financial-product/securities/VNM',
    headers: { 'User-Agent': UA, 'Accept': 'application/json' },
  },
  {
    name: 'D. SSI iboard',
    url: 'https://iboard-query.ssi.com.vn/stock/VNM',
    headers: { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://iboard.ssi.com.vn/' },
  },
  {
    name: 'E. Vietstock (api tài chính)',
    url: 'https://api.vietstock.vn/ta/history?symbol=VNM&resolution=D&from=1748736000&to=1781000000',
    headers: { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://stockchart.vietstock.vn/' },
  },
];

const results = [];
for (const s of sources) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: s.url, headers: s.headers, json: false, timeout: 20000,
    });
    const body = typeof res === 'string' ? res : JSON.stringify(res);
    results.push({ source: s.name, status: '✅ SỐNG', sample: body.slice(0, 400) });
  } catch (e) {
    results.push({ source: s.name, status: '❌ ' + (e.message || String(e)), sample: '' });
  }
}

return results.map(r => ({ json: r }));
